#!/usr/bin/env bash
# make_code_archive.sh — build a submission-ready code archive for the manuscript
# "Shared Hub Genes and Immune Signatures of Sepsis and ARDS: A Multi-Omics Integration".
#
# The archive is what you upload to GitHub and then snapshot on Zenodo to obtain a DOI.
# It contains analysis code, derived numeric results, and the manuscript text.
# It deliberately EXCLUDES raw public data (re-downloadable from GEO / IEU OpenGWAS / FinnGen)
# and large binary objects (Seurat / Scanpy / CellChat .rds and .h5ad files), which are
# regenerated by the scripts and would exceed GitHub's 100 MB per-file limit.
#
# Usage:   bash scripts/make_code_archive.sh [--dry-run]
# Output:  ../code_archive/            (staging tree)
#          ../code_archive.zip         (upload this to Zenodo if you prefer a single file)
#
# After this script finishes, follow the steps in
# AJRCCM_submission/09_review_deAI_2026-09-25/55_Code_Archive_and_DOI_Plan_2026-10-19.md

set -euo pipefail

DRY_RUN=0
[ "${1:-}" = "--dry-run" ] && DRY_RUN=1

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${HERE}/.." && pwd)"
OUT="${ROOT}/code_archive"

echo "project root : ${ROOT}"
echo "archive root : ${OUT}"

if [ "${DRY_RUN}" -eq 0 ]; then
  rm -rf "${OUT}"
  mkdir -p "${OUT}"/{analysis,results,manuscript,environment}
fi

# ---------------------------------------------------------------- 1. analysis code
echo "-- copying analysis code"
if [ "${DRY_RUN}" -eq 0 ]; then
  rsync -a --include='*/' --include='*.R' --include='*.r' --include='*.py' \
           --include='*.sh' --include='*.Rmd' --include='*.yml' --include='*.yaml' \
           --exclude='*' "${ROOT}/scripts/" "${OUT}/analysis/" 2>/dev/null \
    || cp -R "${ROOT}/scripts/." "${OUT}/analysis/"
fi
echo "   scripts: $(find "${ROOT}/scripts" -type f \( -name '*.R' -o -name '*.py' -o -name '*.sh' \) | wc -l | tr -d ' ')"

# ---------------------------------------------------------------- 2. derived results (numeric only)
# Intermediate matrices (CellOracle coefficient matrices, raw GEO series matrices,
# full HPA downloads) are regenerated by the scripts or re-downloadable, and are
# excluded to keep the repository well under GitHub's size guidance.
echo "-- copying derived numeric results (CSV/XLSX/TSV/TXT <= 5 MB, intermediates excluded)"
COPIED=0
if [ "${DRY_RUN}" -eq 0 ]; then
  while IFS= read -r d; do
    name="$(basename "${d}")"
    [ "${name}" = "00_rawdata" ] && continue
    mkdir -p "${OUT}/results/${name}"
    find "${d}" -type f \( -name '*.csv' -o -name '*.tsv' -o -name '*.xlsx' -o -name '*.txt' \) \
         -size -5M \
         ! -name 'CellOracle_coef*' \
         ! -name '*_series_matrix.txt' \
         -exec cp {} "${OUT}/results/${name}/" \; 2>/dev/null || true
  done < <(find "${ROOT}" -maxdepth 1 -type d -name '[0-9][0-9]_*' | sort)
  COPIED=$(find "${OUT}/results" -type f | wc -l | tr -d ' ')
fi
echo "   result files: ${COPIED}"

# ---------------------------------------------------------------- 3. manuscript text
echo "-- copying manuscript text"
if [ "${DRY_RUN}" -eq 0 ]; then
  SUB="${ROOT}/AJRCCM_submission/09_review_deAI_2026-09-25"
  cp "${SUB}/02_Manuscript_Revised.md"                 "${OUT}/manuscript/" 2>/dev/null || true
  cp "${SUB}/03_Manuscript_Translation_CN.md"          "${OUT}/manuscript/" 2>/dev/null || true
  cp "${SUB}/Supplementary_Methods.md"                 "${OUT}/manuscript/" 2>/dev/null || true
  cp "${SUB}/Supplementary_Materials.md"               "${OUT}/manuscript/" 2>/dev/null || true
  cp "${SUB}/04_Modification_Log.md"                   "${OUT}/manuscript/" 2>/dev/null || true
  cp "${SUB}/figures/Figure_legends.md"                "${OUT}/manuscript/" 2>/dev/null || true
  mkdir -p "${OUT}/manuscript/supplementary_tables"
  find "${SUB}/figures/supplementary_tables" -maxdepth 1 -type f -name '*.csv' \
       -exec cp {} "${OUT}/manuscript/supplementary_tables/" \; 2>/dev/null || true
fi

# ---------------------------------------------------------------- 4. environment + metadata
echo "-- writing environment and metadata files"
if [ "${DRY_RUN}" -eq 0 ]; then
  R --version | head -1 > "${OUT}/environment/R_version.txt" 2>/dev/null || echo "R (version not captured)" > "${OUT}/environment/R_version.txt"
  python3 --version  > "${OUT}/environment/python_version.txt" 2>/dev/null || true
  Rscript -e 'ip <- installed.packages()[, c("Package","Version")]; write.csv(ip[order(ip[,1]), ], file=file.path(Sys.getenv("ARCHIVE_ENV_OUT","environment/R_packages.csv")), row.names=FALSE)' 2>/dev/null || true
fi

cat > /tmp/_gitignore <<'EOF'
# large binary single-cell objects (regenerate with the scripts)
*.rds
*.h5ad
*.h5seurat
*.loom
*.rds.corrupt.bak
# raw public data (re-download with scripts/download_data.sh)
00_rawdata/
# figures (large TIFFs; shipped with the manuscript, not the code archive)
*.tiff
*.tif
__pycache__/
.Rhistory
.DS_Store
EOF

cat > /tmp/_license <<'EOF'
MIT License

Copyright (c) 2026 the authors of "Shared Hub Genes and Immune Signatures of
Sepsis and ARDS: A Multi-Omics Integration".

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.
EOF

if [ "${DRY_RUN}" -eq 0 ]; then
  cp /tmp/_gitignore "${OUT}/.gitignore"
  cp /tmp/_license   "${OUT}/LICENSE"
fi

# ---------------------------------------------------------------- 5. manifest
if [ "${DRY_RUN}" -eq 0 ]; then
  echo "-- writing MANIFEST.txt (path + size + sha256)"
  (cd "${OUT}" && find . -type f ! -name 'MANIFEST.txt' -print0 \
     | sort -z \
     | while IFS= read -r -d '' f; do
         printf '%s\t%s\t%s\n' "${f#./}" \
           "$(wc -c < "${f}" | tr -d ' ')" \
           "$(shasum -a 256 "${f}" | cut -c1-64)"
       done > MANIFEST.txt)
  echo "   manifest entries: $(wc -l < "${OUT}/MANIFEST.txt" | tr -d ' ')"
fi

# ---------------------------------------------------------------- 6. zip
if [ "${DRY_RUN}" -eq 0 ]; then
  rm -f "${OUT}.zip"
  echo "-- creating zip"
  (cd "$(dirname "${OUT}")" && zip -rq "$(basename "${OUT}").zip" "$(basename "${OUT}")" \
      -x '*.DS_Store' '*/__pycache__/*')
  echo "   archive size: $(du -sh "${OUT}" | cut -f1)"
  echo "   zip size    : $(du -sh "${OUT}.zip" | cut -f1)"
fi

echo "-- listing excluded categories (NOT included in the archive):"
echo "   00_rawdata/            public GEO / IEU OpenGWAS / FinnGen inputs"
echo "   *.rds, *.h5ad, *.loom  large single-cell objects, regenerated by the scripts"
echo "   *.tiff / *.pdf / *.png figure panels (ship with the manuscript submission)"

echo "done."
